// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;

    function setUp() public { c = new Proxy(); }

    function testFuzz_property(bool succeed, bytes memory data, address actor) public {
        vm.assume(actor != address(0));
        Succeeder s = new Succeeder();
        Reverter r = new Reverter();
        address callee = succeed ? address(s) : address(r);
        vm.prank(actor);
        bool ok;
        try c.forward(callee, data) { ok = true; } catch { ok = false; }
        assertTrue(ok == succeed);
    }
}

contract Succeeder {
    fallback() external payable { }
}

contract Reverter {
    fallback() external payable { revert(); }
}
